import{_ as t,o,c as a,a5 as s}from"./chunks/framework.DukzBDYY.js";const r="/images/schedules.jpg",d="/images/schedule.jpg",g=JSON.parse('{"title":"Setting Up a Schedule","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/schedules.md","filePath":"getting-started/schedules.md"}'),n={name:"getting-started/schedules.md"};function i(h,e,l,c,u,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="setting-up-a-schedule" tabindex="-1">Setting Up a Schedule <a class="header-anchor" href="#setting-up-a-schedule" aria-label="Permalink to &quot;Setting Up a Schedule&quot;">​</a></h1><p>Each shipping method has its own schedule. Go to <strong>Delivery Slots → Schedules</strong> to see them all.</p><p><img src="'+r+'" alt="The Schedules page listing Local delivery with 6 windows and 3 zones, and Pick up in store with 9 windows"></p><p>Click a shipping method to edit its schedule. Shipping methods themselves are created in <strong>Commerce → Store Management → Shipping Methods</strong>.</p><p><img src="'+d+'" alt="The schedule for Local delivery: six time windows, an 8pm cut-off, closed days for Christmas and New Year, two changes on a date, and three zones"></p><h2 id="offer-delivery-times" tabindex="-1">Offer delivery times <a class="header-anchor" href="#offer-delivery-times" aria-label="Permalink to &quot;Offer delivery times&quot;">​</a></h2><p>Turn this on for customers to choose a slot for the method. While it’s on, customers can’t pay for an order with this method until they’ve chosen one. Turn it off to stop offering slots without losing the schedule.</p><h2 id="time-windows" tabindex="-1">Time windows <a class="header-anchor" href="#time-windows" aria-label="Permalink to &quot;Time windows&quot;">​</a></h2><p>Each row is a window, such as 8–10am, that runs on the ticked days.</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Start</strong>, <strong>End</strong></td><td>The window’s times, in the site’s time zone</td></tr><tr><td><strong>Mon</strong> … <strong>Sun</strong></td><td>The days it runs</td></tr><tr><td><strong>Orders per slot</strong></td><td>How many orders the window takes on each day. 10 means ten orders on Monday, ten on Tuesday, and so on</td></tr></tbody></table><p>To have shorter Saturdays, untick Saturday on the afternoon windows. For a window that takes more orders on one day, add a second row with the same times for that day.</p><p>Windows don’t have to be the same length. Pickup is often hourly, and delivery two- or four-hourly.</p><h2 id="ordering-window" tabindex="-1">Ordering window <a class="header-anchor" href="#ordering-window" aria-label="Permalink to &quot;Ordering window&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Next-day cut-off</strong></td><td>Orders for tomorrow close at this time today. With 8:00 PM, an order placed at 9pm on Monday can’t choose Tuesday. Leave it blank for no cut-off</td></tr><tr><td><strong>Same-day slots</strong></td><td>Let customers choose a slot later today. Off by default</td></tr><tr><td><strong>Book at least</strong></td><td>How many hours before a slot starts it can still be chosen. With 2 hours, the 2–4pm slot closes at noon</td></tr><tr><td><strong>Show slots up to</strong></td><td>How many days ahead the picker shows</td></tr></tbody></table><h2 id="closed-days" tabindex="-1">Closed days <a class="header-anchor" href="#closed-days" aria-label="Permalink to &quot;Closed days&quot;">​</a></h2><p>Dates with no slots, such as public holidays or a stocktake. The label is shown to customers in place of the slots, such as “Christmas Day”. Without a label, the day shows as “Closed”.</p><p>Weekdays with no windows, such as Sunday above, are closed every week; you don’t need to add them.</p><h2 id="changes-on-a-date" tabindex="-1">Changes on a date <a class="header-anchor" href="#changes-on-a-date" aria-label="Permalink to &quot;Changes on a date&quot;">​</a></h2><p>A different limit for one window on one date, without changing the weekly schedule. Use it when a driver is away (fewer orders), for a big catering order (more), or to close one window for the day (0).</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>The day</td></tr><tr><td><strong>Window starting</strong></td><td>The start time of the window to change, such as 8:00 AM</td></tr><tr><td><strong>Orders per slot</strong></td><td>The limit for that window on that day. 0 closes it</td></tr></tbody></table><p>To close the whole day, use <strong>Closed days</strong> instead.</p><h2 id="zones" tabindex="-1">Zones <a class="header-anchor" href="#zones" aria-label="Permalink to &quot;Zones&quot;">​</a></h2><p>With Geo Maps installed, add the areas you deliver to, and give each its own days, order limit and fee. See <a href="/guides/zones">Delivery Zones</a>.</p><h2 id="pickup" tabindex="-1">Pickup <a class="header-anchor" href="#pickup" aria-label="Permalink to &quot;Pickup&quot;">​</a></h2><p>Pickup works the same way: create a <em>Pick up in store</em> shipping method in Commerce, with a rule that matches every order, then give it a schedule. Turn on <strong>Same-day slots</strong> and set <strong>Book at least</strong> to 1 hour for “ready in an hour”. See the <a href="/examples/click-and-collect">click and collect example</a>.</p><h2 id="several-stores" tabindex="-1">Several stores <a class="header-anchor" href="#several-stores" aria-label="Permalink to &quot;Several stores&quot;">​</a></h2><p>On a multi-store Commerce site, the Schedules page lists each store’s shipping methods separately, and each method has its own schedule.</p>',27)])])}const w=t(n,[["render",i]]);export{g as __pageData,w as default};
